-- Create a database for your app
CREATE DATABASE myapp;

-- Create a role (user) with a password
CREATE ROLE app_user WITH LOGIN PASSWORD 'strongpassword';

-- Grant all privileges on the database to the role
GRANT ALL PRIVILEGES ON DATABASE myapp TO app_user;

-- Connect to the new database
\c myapp

-- Grant usage on the public schema (needed in Postgres 15+)
GRANT USAGE ON SCHEMA public TO app_user;
GRANT CREATE ON SCHEMA public TO app_user;

-- Delete a database (all data gone)
DROP DATABASE IF EXISTS myapp;
